    // A connector is compiled and registered against the local EVM's registry, so each
    // dependency's content hash is read from there: it names the exact content the
    // connector was built against, and it exists as soon as the dependency is deployed,
    // before any event about it has been projected.
    static asio::awaitable<std::expected<std::vector<pt::ArtifactDependency>, pt::PTDeployError>>
    collectConnectorDependencies(
        evm::EVM & evm,
        const Connector & connector)
    {
        std::set<std::pair<pt::EntityKind, std::string>> names;
        for(const auto & dimension : connector.dimensions())
        {
            for(const auto & transformation : dimension.transformations())
            {
                if(!transformation.name().empty())
                {
                    names.emplace(pt::EntityKind::TRANSFORMATION, transformation.name());
                }
            }
            if(!dimension.composite().empty())
            {
                names.emplace(pt::EntityKind::CONNECTOR, dimension.composite());
            }
            for(const auto & [_, binding] : dimension.bindings())
            {
                if(!binding.empty()) names.emplace(pt::EntityKind::CONNECTOR, binding);
            }
        }
        if(!connector.condition_name().empty())
        {
            names.emplace(pt::EntityKind::CONDITION, connector.condition_name());
        }

        std::vector<pt::ArtifactDependency> dependencies;
        dependencies.reserve(names.size());
        for(const auto & [kind, name] : names)
        {
            std::vector<std::uint8_t> call = chain::constructSelector("getEntityContentHash(uint8,string)");
            const std::vector<std::uint8_t> key = pt::abi::encodeTuple({
                pt::abi::uintComponent(static_cast<std::uint64_t>(kind)),
                pt::abi::stringComponent(name)});
            call.insert(call.end(), key.begin(), key.end());

            co_await evm.setGas(evm.getRegistryAddress(), evm::DEFAULT_GAS_LIMIT);
            const auto output = co_await evm.execute(
                evm.getRegistryAddress(), evm.getRegistryAddress(), std::move(call), evm::DEFAULT_GAS_LIMIT, 0);
            if(!output || output->size() != 32)
            {
                spdlog::error("Cannot bundle connector '{}': reading dependency '{}' failed", connector.name(), name);
                co_return std::unexpected(pt::PTDeployError{});
            }

            evmc::bytes32 content_hash{};
            std::ranges::copy(*output, content_hash.bytes);
            if(content_hash == evmc::bytes32{})
            {
                spdlog::error("Cannot bundle connector '{}': dependency '{}' is not registered", connector.name(), name);
                co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::INVALID_INPUT});
            }
            dependencies.push_back({.kind = kind, .name = name, .content_hash = chain::bytes32ToHex(content_hash)});
        }
        co_return dependencies;
    }

    // Loads the retained local definition of an entity created on this server.
    template<class T>
    static std::optional<T> _loadSingleJSONRecord(const std::filesystem::path & file_path)
    {
        std::error_code ec;
        if(!std::filesystem::exists(file_path, ec) || ec)
        {
            return std::nullopt;
        }

        std::ifstream file(file_path);
        if(!file.is_open())
        {
            spdlog::error("Failed to open JSON record file: {}", file_path.string());
            return std::nullopt;
        }

        std::string json((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        file.close();

        auto loaded_result = parse::parseFromJson<T>(json, parse::use_protobuf);
        if(!loaded_result)
        {
            spdlog::error("Failed to parse JSON record file: {}", file_path.string());
            return std::nullopt;
        }

        return std::move(*loaded_result);
    }

    // The definition of a local connector: its retained JSON, or its registry record.
    static asio::awaitable<std::optional<ConnectorRecord>> _loadLocalConnector(
        registry::Registry & registry,
        const std::string & name,
        const std::filesystem::path & storage_path)
    {
        if(!pt::isValidEntityName(name)) co_return std::nullopt;
        if(auto stored = _loadSingleJSONRecord<ConnectorRecord>(storage_path / "connectors" / (name + ".json")))
        {
            co_return stored;
        }

        const auto handle = co_await registry.getConnectorRecordHandle(name);
        if(!handle || !*handle) co_return std::nullopt;
        co_return ConnectorRecord(**handle);
    }

    template<class T>
    static absl::flat_hash_map<std::string, T> _loadJSONRecords(std::filesystem::path dir)
    {
        absl::flat_hash_map<std::string, T> loaded_data;
        parse::Result<T> loaded_result;

        std::size_t json_files_seen = 0;
        std::size_t loaded_records = 0;
        std::size_t open_failures = 0;
        std::size_t parse_failures = 0;
        
        bool success = true;

        try {
            for (const auto& entry : std::filesystem::directory_iterator(dir)) 
            {
                if(!entry.is_regular_file() || entry.path().extension() != ".json")
                {
                    continue;
                }

                ++json_files_seen;
                
                spdlog::debug("JSON import scanning file '{}'", entry.path().string());

                std::ifstream file(entry.path());

                if(!file.is_open())
                {
                    spdlog::error(std::format("Failed to open file: {}", entry.path().string()));
                    ++open_failures;
                    continue;
                }

                std::string json((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
                file.close();

                loaded_result = parse::parseFromJson<T>(json, parse::use_protobuf);
                if(!loaded_result)
                {
                    spdlog::error(std::format("Failed to parse JSON: {}", json));
                    ++parse_failures;
                    continue;
                }

                loaded_data.try_emplace(entry.path().stem().string(), std::move(*loaded_result));
                ++loaded_records;
            }
        } 
        catch (const std::filesystem::filesystem_error& e) 
        {
            spdlog::error(std::format("Filesystem error: {}", e.what()));
            success = false;
        } 
        catch (const std::exception& e) 
        {
            spdlog::error(std::format("Exception: {}", e.what()));
            success = false;
        }

        if(!success)
        {
            return {};
        }

        spdlog::debug(
            "JSON import scan finished for '{}': files={}, loaded={}, open_failures={}, parse_failures={}",
            dir.string(),
            json_files_seen,
            loaded_records,
            open_failures,
            parse_failures);

        return loaded_data;
    }

    std::string ptSourceRevision(const std::filesystem::path & pt_path)
    {
        return ptSourceRevisionImpl(pt_path);
    }

    bool ensurePTBuildVersion(const std::filesystem::path & storage_path)
    {
        const std::filesystem::path marker_path = storage_path / "pt_solidity_build_version";

        std::string current_version;
        if(std::filesystem::exists(marker_path))
        {
            std::ifstream marker_in(marker_path);
            if(marker_in.is_open())
            {
                std::getline(marker_in, current_version);
            }
        }

        if(current_version == PT_BUILD_VERSION)
        {
            spdlog::debug("PT Solidity build cache version is up-to-date: {}", PT_BUILD_VERSION);
            return true;
        }

        spdlog::info(
            "PT Solidity build cache version changed from '{}' to '{}'. Cleaning stale build artifacts.",
            current_version.empty() ? "<none>" : current_version,
            PT_BUILD_VERSION
        );

        try
        {
            for(const std::string & entity_dir : PT_STORAGE_ENTITY_DIRS)
            {
                const std::filesystem::path build_dir = storage_path / entity_dir / "build";
                std::size_t removed_count = 0;

                if(std::filesystem::exists(build_dir))
                {
                    for(const auto & entry : std::filesystem::directory_iterator(build_dir))
                    {
                        if(!entry.is_regular_file())
                        {
                            continue;
                        }

                        const std::filesystem::path file_path = entry.path();
                        const std::string ext = file_path.extension().string();
                        if(ext == ".bin" || ext == ".bin-runtime" || ext == ".abi" || ext == ".json" || ext == ".sol")
                        {
                            std::filesystem::remove(file_path);
                            ++removed_count;
                        }
                    }
                }

                spdlog::info("PT build cleanup '{}': removed {} cached artifacts", entity_dir, removed_count);
            }
        }
        catch(const std::filesystem::filesystem_error & e)
        {
            spdlog::error("Failed to cleanup PT build artifacts: {}", e.what());
            return false;
        }

        std::ofstream marker_out(marker_path, std::ios::out | std::ios::trunc);
        if(!marker_out.is_open())
        {
            spdlog::error("Failed to write PT build version marker '{}'", marker_path.string());
            return false;
        }

        marker_out << PT_BUILD_VERSION;
        marker_out.close();

        spdlog::info("PT Solidity build cache marker updated: {}", PT_BUILD_VERSION);
        return true;
    }

    template<class RecordType>
    static asio::awaitable<bool> _saveJsonRecord(const std::string & name, RecordType record, const std::filesystem::path out_dir)
    {
        if(std::filesystem::exists(out_dir) == false)
        {
            spdlog::error("Directory {} does not exists", out_dir.string());
            co_return false;
        }

        const auto parsing_result = parse::parseToJson(record, parse::use_protobuf);
        if(!parsing_result)
        {
            spdlog::error("Failed to parse record `{}`", name);
            co_return false;
        }

        std::ofstream output_file(out_dir / (name + ".json"), std::ios::out | std::ios::trunc);

        output_file << *parsing_result;
        output_file.close();

        co_return true;
    }

    // keccak256 over the PT (and library) sources a compilation read, by stable source
    // unit name and content hash, excluding the entity's own generated unit. Identifies
    // exactly the protocol code an artifact was built against, so an unrelated PT change
    // does not change it.
    static std::string _sourcesRevision(
        const std::map<std::string, std::string> & sources,
        const std::string & own_unit)
    {
        std::string preimage;
        for(const auto & [unit, content_hash] : sources)
        {
            if(unit == own_unit) continue;
            preimage += unit;
            preimage.push_back('\0');
            preimage += content_hash;
            preimage.push_back('\0');
        }
        return chain::bytes32ToHex(chain::keccakString(preimage));
    }

    // Compiles the entity, builds its artifact bundle and binds both into a publication.
    // Shared by local simulation deployment and remote publication so an entity is
    // registered the same way on the local EVM and on a real chain; `ctor_prefix_args`
    // and the registry the publication is bound to are the only differences.
    template<class T, class InternalGetter, class SolidityCodeCtor>
    static asio::awaitable<std::expected<PreparedPublication, pt::PTDeployError>> _preparePublication(
        evm::EVM & evm,
        T object,
        InternalGetter getter,
        const std::filesystem::path out_dir,
        SolidityCodeCtor solidity_code_ctor,
        pt::EntityKind entity_kind,
        std::vector<std::uint8_t> ctor_prefix_args,
        std::optional<pt::ConnectorRegistration> registration,
        std::vector<pt::ArtifactDependency> dependencies
    )
    {
        using Internal_t = std::invoke_result_t<InternalGetter, T>;
        const Internal_t & internal = std::invoke(getter, object);
        const std::string name = internal.name();
        spdlog::debug("_preparePublication '{}'", name);

        // The name becomes a Solidity contract identifier and a file name.
        if(!pt::isValidEntityName(name))
        {
            spdlog::error("Entity name '{}' is not a valid identifier", name);
            co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::INVALID_INPUT});
        }

        const auto address_result = evmc::from_hex<chain::Address>(object.owner());
        if(!address_result)
        {
            spdlog::error("Failed to parse address");
            co_return std::unexpected(pt::PTDeployError{pt::PTDeployError::Kind::INVALID_INPUT});
        }

        // Generated source is part of the bundle whose hash the publication carries.
        using SolidityCodeResult_t = std::decay_t<std::invoke_result_t<SolidityCodeCtor, Internal_t>>;
        const auto solidity_code_result = std::invoke(std::forward<SolidityCodeCtor>(solidity_code_ctor), internal);

        std::string solidity_code;
        if constexpr(std::is_same_v<SolidityCodeResult_t, parse::Result<std::string>>)
        {
            if(!solidity_code_result)
            {
                spdlog::error(
                    "Failed to construct Solidity code for `{}`: parse error kind={} ({})",
                    name,
                    static_cast<int>(solidity_code_result.error().kind),
                    solidity_code_result.error().message);
                co_return std::unexpected(pt::PTDeployError{pt::PTDeployError::Kind::INVALID_INPUT});
            }

            solidity_code = *solidity_code_result;
        }
        else if constexpr(std::is_same_v<SolidityCodeResult_t, std::string>)
        {
            solidity_code = solidity_code_result;
        }
        else
        {
            static_assert(utils::always_false<SolidityCodeResult_t>, "Unsupported Solidity code constructor return type");
        }

        if(solidity_code.empty())
        {
            spdlog::error("Failed to construct Solidity code for `{}`: empty source", name);
            co_return std::unexpected(pt::PTDeployError{pt::PTDeployError::Kind::INVALID_INPUT});
        }

        const std::string unit_name = name + ".sol";
        const auto compiled = co_await evm.compileSource(unit_name, solidity_code, name, out_dir / "build");
        if(!compiled)
        {
            spdlog::error("Failed to compile `{}`: {}", name, compiled.error().message);
            co_return std::unexpected(compiled.error().kind == evm::CompileError::Kind::REJECTED
                ? pt::PTDeployError{.kind = pt::PTDeployError::Kind::INVALID_INPUT}
                : pt::PTDeployError{});
        }

        pt::Publication publication;
        publication.kind = entity_kind;
        publication.name = name;
        publication.owner = *address_result;
        publication.metadata_hash = pt::computeMetadataHash(entity_kind, name);
        publication.deadline = std::numeric_limits<std::uint64_t>::max();
        if(registration)
        {
            publication.registration_hash = pt::computeRegistrationHash(*registration);
        }

        const auto definition_json = parse::parseToJson(object, parse::use_protobuf);
        if(!definition_json)
        {
            spdlog::error("Failed to serialize artifact definition for `{}`", name);
            co_return std::unexpected(pt::PTDeployError{});
        }

        nlohmann::json definition;
        try
        {
            definition = nlohmann::json::parse(*definition_json);
        }
        catch(const std::exception & error)
        {
            spdlog::error("Failed to canonicalize artifact definition for `{}`: {}", name, error.what());
            co_return std::unexpected(pt::PTDeployError{});
        }

        std::string source_fragment;
        if constexpr(requires { internal.sol_src(); }) source_fragment = internal.sol_src();

        const evm::CompilerSettings & settings = evm::SOLC_SETTINGS;
        const auto bundle_bytes = pt::encodeArtifactBundle(pt::ArtifactBundle{
            .kind = entity_kind,
            .name = name,
            .definition = std::move(definition),
            .sol_src = std::move(source_fragment),
            .generated_solidity = solidity_code,
            .pt_revision = _sourcesRevision(compiled->sources, unit_name),
            .solc_version = evm.solcVersion(),
            .evm_version = std::string(settings.evm_version),
            .optimizer = settings.optimizer,
            .optimizer_runs = settings.optimizer_runs,
            .via_ir = settings.via_ir,
            .imports = solidityImports(solidity_code),
            .creation_code_hash = chain::bytes32ToHex(
                chain::keccakBytes(compiled->creation_code.data(), compiled->creation_code.size())),
            .runtime_code_hash = chain::bytes32ToHex(
                chain::keccakBytes(compiled->runtime_code.data(), compiled->runtime_code.size())),
            .metadata_hash = chain::bytes32ToHex(publication.metadata_hash),
            .dependencies = dependencies});
        if(!bundle_bytes)
        {
            spdlog::error("Failed to build artifact bundle for `{}`: {}", name, bundle_bytes.error());
            co_return std::unexpected(pt::PTDeployError{});
        }

        // The content hash is the protocol's commitment to the bundle; the bundle itself is
        // not kept.
        publication.content_hash = pt::computeContentHash(*bundle_bytes);
        const std::string content_hash = chain::bytes32ToHex(publication.content_hash);

        // Publication is one transaction: the registry deploys with CREATE2, validates the
        // deployed runtime against these hashes, then registers and emits the event.
        std::vector<std::uint8_t> creation_code = compiled->creation_code;
        creation_code.insert(creation_code.end(), ctor_prefix_args.begin(), ctor_prefix_args.end());
        creation_code.insert(
            creation_code.end(), publication.content_hash.bytes, publication.content_hash.bytes + 32);
        creation_code.insert(
            creation_code.end(), publication.metadata_hash.bytes, publication.metadata_hash.bytes + 32);

        publication.creation_code_hash = chain::keccakBytes(creation_code.data(), creation_code.size());
        publication.runtime_code_hash =
            chain::keccakBytes(compiled->runtime_code.data(), compiled->runtime_code.size());

        co_return PreparedPublication{
            .publication = std::move(publication),
            .creation_code = std::move(creation_code),
            .runtime_code = compiled->runtime_code,
            .artifact_bytes = *bundle_bytes,
            .content_hash = content_hash,
            .registration = std::move(registration),
            .dependencies = std::move(dependencies)
        };
    }

    // Calldata registering `prepared` with an empty owner signature: the sender is the owner.
    static std::vector<std::uint8_t> _encodePublishCall(const PreparedPublication & prepared)
    {
        switch(prepared.publication.kind)
        {
        case pt::EntityKind::CONNECTOR:
            return pt::encodePublishConnectorCall(
                prepared.creation_code, prepared.publication, *prepared.registration, {});
        case pt::EntityKind::TRANSFORMATION:
            return pt::encodePublishTransformationCall(prepared.creation_code, prepared.publication, {});
        case pt::EntityKind::CONDITION:
            return pt::encodePublishConditionCall(prepared.creation_code, prepared.publication, {});
        }
        return {};
    }

    // Registers `prepared` with the in-process EVM's registry and returns the entity's
    // address. The owner sends the publication itself, so the registry accepts an empty
    // owner signature; the nonce is the local registry's.
    static asio::awaitable<std::expected<chain::Address, pt::PTDeployError>> _publishLocally(
        evm::EVM & evm,
        PreparedPublication & prepared)
    {
        pt::Publication & publication = prepared.publication;
        const chain::Address address = publication.owner;
        const std::string name = publication.name;

        co_await evm.addAccount(address, evm::DEFAULT_GAS_LIMIT);
        co_await evm.setGas(address, evm::DEFAULT_GAS_LIMIT);

        const auto nonce_result = co_await evm.execute(
            address,
            evm.getRegistryAddress(),
            pt::encodePublicationNonceCall(address),
            evm::DEFAULT_GAS_LIMIT,
            0);
        const auto nonce = nonce_result ? chain::readUint64Word(*nonce_result) : std::nullopt;
        if(!nonce)
        {
            spdlog::error("Failed to read publication nonce for `{}`", name);
            co_return std::unexpected(pt::PTDeployError{});
        }
        publication.nonce = *nonce;

        const auto publish_result = co_await evm.execute(
            address,
            evm.getRegistryAddress(),
            _encodePublishCall(prepared),
            evm::DEFAULT_GAS_LIMIT,
            0);

        if(!publish_result)
        {
            const auto & error = publish_result.error();
            spdlog::error("Failed to publish object `{}`: {}", name, std::format("{}", error.kind));

            const auto pt_error = parse::decodeBytes<pt::PTDeployError>(error.result_bytes);
            if(!pt_error)
            {
                std::string output_hex = "<empty>";
                if(!error.result_bytes.empty())
                {
                    output_hex = evmc::hex(evmc::bytes_view{error.result_bytes.data(), error.result_bytes.size()});
                }

                spdlog::error(std::format(
                    "Failed to parse PTDeployError: {} ({}) output={}",
                    static_cast<int>(pt_error.error().kind),
                    pt_error.error().message,
                    output_hex));
                co_return std::unexpected(pt::PTDeployError{});
            }

            co_return std::unexpected(pt_error.value());
        }

        const auto object_address_res = chain::readAddressWord(*publish_result);
        if(!object_address_res)
        {
            spdlog::error("Failed to parse published address for `{}`", name);
            co_return std::unexpected(pt::PTDeployError{pt::PTDeployError::Kind::INVALID_INPUT});
        }

        spdlog::info("Object address '{}': {}", name, evmc::hex(*object_address_res));
        co_return *object_address_res;
    }

    // Deploys through the registry factory on the in-process EVM.
    template<class T, class InternalGetter, class SolidityCodeCtor>
    static asio::awaitable<std::expected<chain::Address, pt::PTDeployError>> _deployObjectLocally(
        evm::EVM & evm,
        registry::Registry & registry,
        T object,
        InternalGetter getter,
        const std::filesystem::path out_dir,
        SolidityCodeCtor solidity_code_ctor,
        pt::EntityKind entity_kind,
        std::vector<std::uint8_t> ctor_prefix_args,
        std::optional<pt::ConnectorRegistration> registration,
        std::vector<pt::ArtifactDependency> dependencies,
        bool persist_json = true
    )
    {
        auto prepared = co_await _preparePublication(
            evm,
            object,
            getter,
            out_dir,
            std::forward<SolidityCodeCtor>(solidity_code_ctor),
            entity_kind,
            std::move(ctor_prefix_args),
            std::move(registration),
            std::move(dependencies));
        if(!prepared)
        {
            co_return std::unexpected(prepared.error());
        }

        const std::string name = prepared->publication.name;

        // The runtime code of a transformation or condition is kept with the registry, as
        // for chain entities. It is stored by its hash before the publication, so the
        // entity is never registered without it.
        if(entity_kind != pt::EntityKind::CONNECTOR
           && !co_await registry.putRuntimeCode(
               chain::bytes32ToHex(prepared->publication.runtime_code_hash), prepared->runtime_code))
        {
            spdlog::error("Failed to store the runtime code of `{}`", name);
            co_return std::unexpected(pt::PTDeployError{});
        }

        const auto published = co_await _publishLocally(evm, *prepared);
        if(!published) co_return std::unexpected(published.error());
        const chain::Address object_address = *published;

        if(persist_json && !co_await _saveJsonRecord(name, std::move(object), out_dir))
        {
            spdlog::error("Failed to save object json '{}'", name);
            co_return std::unexpected(pt::PTDeployError{});
        }

        spdlog::debug("Object '{}' added", name);
        co_return object_address;
    }


    // Keeps the first reason a chain entity could not be deployed: the deepest dependency
    // fails first, and it is the one to fix.
    static void _noteFailure(std::string * failure, std::string reason)
    {
        spdlog::error("{}", reason);
        if(failure && failure->empty()) *failure = std::move(reason);
    }

    // Deploys the chain entity at `location` on the in-process EVM by running the creation
    // code the chain deployed it from, so it starts from exactly the constructor state the
    // chain has. A connector's registry constructor argument is pointed at the local
    // registry, where its dependencies are deployed the same way. The local registry checks
    // the result against the entity's registry event as the chain registry did.
    static asio::awaitable<std::expected<chain::Address, std::string>> _replayChainEntity(
        evm::EVM & evm,
        registry::Registry & registry,
        const pt::EntityKind kind,
        const std::string & name,
        const registry::EntityLocation & location,
        const std::string & owner,
        std::optional<pt::ConnectorRegistration> registration = std::nullopt)
    {
        const registry::EntitySource & source = location.source;
        const std::string label = std::format("{} '{}'", pt::entityKindName(kind), name);

        auto creation_code = co_await registry.getChainCreationCode(source.source_id, location.address);
        if(!creation_code)
        {
            co_return std::unexpected(source.log_index < 0
                ? std::format("{} was read from registry state and its publication could not be located, "
                    "so its constructor state cannot be reproduced", label)
                : std::format("{}: its creation code could not be recovered from its publication transaction "
                    "(a relay that builds the call on chain), so its constructor state cannot be reproduced", label));
        }

        const auto owner_address = evmc::from_hex<chain::Address>(owner);
        const auto content_hash = evmc::from_hex<evmc::bytes32>(source.content_hash);
        const auto metadata_hash = evmc::from_hex<evmc::bytes32>(source.metadata_hash);
        const auto runtime_code_hash = evmc::from_hex<evmc::bytes32>(source.runtime_code_hash);
        if(!owner_address || !content_hash || !metadata_hash || !runtime_code_hash)
        {
            co_return std::unexpected(std::format("{}: its registry record is malformed", label));
        }

        if(kind == pt::EntityKind::CONNECTOR)
        {
            // A PT connector's constructor arguments end with its registry, content hash and
            // metadata hash words.
            constexpr std::size_t TRAILING_ARGUMENT_BYTES = 3 * 32;
            const auto chain_registry = evmc::from_hex<chain::Address>(source.registry_address);
            const auto registry_word = creation_code->size() >= TRAILING_ARGUMENT_BYTES
                ? creation_code->end() - TRAILING_ARGUMENT_BYTES
                : creation_code->end();
            const std::vector<std::uint8_t> chain_registry_word =
                chain_registry ? evm::encodeAsArg(*chain_registry) : std::vector<std::uint8_t>{};
            if(!registration || registry_word == creation_code->end() || chain_registry_word.empty()
               || !std::equal(chain_registry_word.begin(), chain_registry_word.end(), registry_word))
            {
                co_return std::unexpected(std::format(
                    "{} does not take its registry as a PT connector constructor does", label));
            }
            std::ranges::copy(evm::encodeAsArg(evm.getRegistryAddress()), registry_word);
        }

        PreparedPublication prepared{
            .publication = pt::Publication{
                .kind = kind,
                .name = name,
                .owner = *owner_address,
                .content_hash = *content_hash,
                .metadata_hash = *metadata_hash,
                .creation_code_hash = chain::keccakBytes(*creation_code),
                .runtime_code_hash = *runtime_code_hash,
                .registration_hash = registration ? pt::computeRegistrationHash(*registration) : evmc::bytes32{},
                .deadline = std::numeric_limits<std::uint64_t>::max()},
            .creation_code = std::move(*creation_code),
            .registration = std::move(registration)};

        const auto published = co_await _publishLocally(evm, prepared);
        if(!published)
        {
            co_return std::unexpected(std::format(
                "{}: replaying its creation code on the local EVM failed (local registry error {})",
                label, static_cast<int>(published.error().kind)));
        }
        spdlog::info("Replayed chain {} on the local EVM", label);
        co_return *published;
    }

    static asio::awaitable<std::expected<chain::Address, pt::PTDeployError>> deployConnectorWithContext(
        evm::EVM & evm,
        registry::Registry & registry,
        ConnectorRecord connector_record,
        const std::filesystem::path & storage_path,
        bool persist_json,
        ConnectorEnsureContext & ensure_context)
    {
        const Connector & connector = connector_record.connector();

        spdlog::debug(
            "JSON import deploy connector '{}': validating dependencies before deploy",
            connector.name());

        for(const auto & dimension : connector.dimensions())
        {
            for(const auto & transformation : dimension.transformations())
            {
                const std::string & transformation_name = transformation.name();
                if(transformation_name.empty())
                {
                    continue;
                }

                if(!co_await ensureTransformationDeployed(evm, registry, transformation_name, storage_path))
                {
                    spdlog::error(
                        "Cannot deploy connector '{}': dependency transformation '{}' is not deployable",
                        connector.name(),
                        transformation_name);
                    co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::TRANSFORMATION_MISSING});
                }
            }

            if(!dimension.composite().empty())
            {
                if(!co_await ensureConnectorDeployedImpl(
                    evm,
                    registry,
                    dimension.composite(),
                    storage_path,
                    ensure_context))
                {
                    spdlog::error(
                        "Cannot deploy connector '{}': dependency connector '{}' is not deployable",
                        connector.name(),
                        dimension.composite());
                    co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::CONNECTOR_MISSING});
                }
            }

            for(const auto & [_, binding_target] : dimension.bindings())
            {
                if(binding_target.empty())
                {
                    continue;
                }

                if(!co_await ensureConnectorDeployedImpl(
                    evm,
                    registry,
                    binding_target,
                    storage_path,
                    ensure_context))
                {
                    spdlog::error(
                        "Cannot deploy connector '{}': binding dependency connector '{}' is not deployable",
                        connector.name(),
                        binding_target);
                    co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::CONNECTOR_MISSING});
                }
            }
        }

        if(!connector.condition_name().empty())
        {
            if(!co_await ensureConditionDeployed(evm, registry, connector.condition_name(), storage_path))
            {
                spdlog::error(
                    "Cannot deploy connector '{}': dependency condition '{}' is not deployable",
                    connector.name(),
                    connector.condition_name());
                co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::CONDITION_MISSING});
            }
        }

        auto registration = pt::buildConnectorRegistration(connector);
        if(!registration)
        {
            spdlog::error("Connector '{}' has a binding slot that is not a uint32", connector.name());
            co_return std::unexpected(pt::PTDeployError{.kind = pt::PTDeployError::Kind::INVALID_INPUT});
        }

        auto dependencies = co_await collectConnectorDependencies(evm, connector);
        if(!dependencies) co_return std::unexpected(dependencies.error());

        co_return co_await _deployObjectLocally(
            evm,
            registry,
            std::move(connector_record),
            &ConnectorRecord::connector,
            storage_path / "connectors",
            &constructConnectorSolidityCode,
            pt::EntityKind::CONNECTOR,
            evm::encodeAsArg(evm.getRegistryAddress()),
            std::move(registration),
            std::move(*dependencies),
            persist_json);
    }

    asio::awaitable<std::expected<chain::Address, pt::PTDeployError>> deployConnector(
        evm::EVM & evm,
        registry::Registry & registry,
        ConnectorRecord connector_record,
        const std::filesystem::path & storage_path,
        bool persist_json)
    {
        ConnectorEnsureContext ensure_context;
        ensure_context.connector_deploy_stack.reserve(64);
        co_return co_await deployConnectorWithContext(
            evm,
            registry,
            std::move(connector_record),
            storage_path,
            persist_json,
            ensure_context);
    }

